  ["2002c5289de4b81d"] = { "Per quanto mi secchi ammetterlo, quella squadra di gnomi laggiù è piuttosto brava. Ai nostri ragazzi serve ogni vantaggio possibile.", "." },
  ["2002e871359a19db"] = { "Quante erbe ha raccolto finora l'⟦Horde=Orda⟧?", "." },
