  ["202b07caa139865b"] = { "Quale compito?", "." },
  ["204d6747f07cdd38"] = { "Ah, grazie di cuore. Ti lascio alla biblioteca mentre mi occupo di questa piccola faccenda.", "." },
  ["204ecd76d4406d97"] = { "Silas, perché alla fiera quasi tutto è gratis? Come fai a guadagnarci?", "." },
  ["2059728dbef81f94"] = { "Sei davvero tra i migliori sarti in circolazione! Congratulazioni, è un onore averti fatto da istruttore!", "." },
  ["205f58d70325ad4d"] = { "<Benvenuto/Benvenuta>, <fratello/sorella> <mio/mia>. Se sei qui per addestrarti, sarò felice di farlo.\n\nSiamo i custodi dell'equilibrio, ora e per sempre, mentre Malfurion giace nel Sogno. Non dimenticarlo mai.", "." },
  ["20635483e2fdeff0"] = { "Bambini, se volete seguirmi, ora andremo a vedere la rocca dove siede sul trono il re Anduin Wrynn in persona.", "." },
  ["2064f13deff28351"] = { "%s sghignazza come un folle.", "." },
  ["2065785476f053f2"] = { "Un minatore? Non devi chiedere se, <ragazzo/ragazza>, solo dove! Quello che cerchi è Yarr, e credo che lo troverai nascosto allo ⟦Steelgrill's Depot=Scalo di Grigliafredda⟧.", "." },
  ["206779ee4d0e2f5b"] = { "Sono testimone di un miracolo che mi sta davanti! In mille anni di prigionia, non ho mai visto un solo esemplare VIVENTE, a parte quei ripugnanti Qiraji e silitidi, entrare in queste camere.", "." },
  ["206e5d1f3a0fb6cf"] = { "Chi è <questo/questa> debole {class} che sfida la mia potenza? Muori, <sciocco/sciocca>!", "." },
  ["206fb056d53fe858"] = { "La ⟦Irondeep Mine=Miniera di Ferrofondo⟧ è in mano ai trogg.", "." },
  ["2078b48244870b94"] = { "Elune ha voluto donarmi abilità ed esperienza. Ora io le trasmetterò a te.", "." },
  ["20797a6ee4e4c575"] = { "Recupera il frammento dello scettro, {name}. Non si deve permettere a Nefarius di distr... distruggere il frammento.", "." },
  ["207dba5d6ae94eca"] = { "<Benvenuto/Benvenuta>, <fratello/sorella> <mio/mia>. Se sei qui per addestrarti, sarò felice di farlo.\n\nSiamo i custodi dell'equilibrio, ora e per sempre, mentre Malfurion giace nel Sogno. Non dimenticarlo mai.", "." },
  ["207ee478c6063323"] = { "BASTA, è finita! Voi stolti finirete nella mia collezione di ossa!", "." },
  ["207fef8147c0e54c"] = { "I dati archiviati in questo deposito confermano la tua acuta affermazione.\n\nIl nano conserva un'affinità con la composizione litica di Azeroth, ma a causa dell'anomalia ambientale ad alto stress nella matrice di sintesi dei Terrigeni, il nano regredisce a una composizione di biomassa predefinita, come osservato nella matrice sotterranea standard.\n\nErgo, la variante nanica deriva effettivamente dalla degenerazione della matrice di creazione dei Terrigeni, come hai dedotto con la tua domanda.", "." },
  ["2083ed2cc6fe1062"] = { "Sento... qualcosa di strano...", "." },
  ["208cb9f3c1faaa8a"] = { "Non posso farci niente, davvero. È solo che questo posto è bellissimo.", "." },
  ["209193f6ae0fa724"] = { "Basta! Adesso le prendi!", "." },
  ["2095904913e69839"] = { "Forse. Ora va', giovane. Cerca consiglio presso il Capoguerra. Di certo vorrà sapere della tua scoperta.", "." },
  ["20a08b1568cc989d"] = { "Ah, la dolce Seriadne. Tutti gli animali sono al sicuro quando sono affidati a lei. La trovi proprio fuori dalla locanda di Dolanaar.", "." },
  ["20a4cd1f248a7b54"] = { "Yip! Io ammazza!", "." },
  ["20a76327a32406f5"] = { "Jin'rokh, mi mancano i miei ⟦Zandalar Freethinker's Armguards=Bracciali Foderati del Libero Pensatore degli Zandalari⟧. Puoi sostituirmeli?", "." },
  ["20b24ea6d81ca82e"] = { "Cos'hai lì? Non ci vedo. La mia vista è pessima. Mettimelo in mano.", "." },
  ["20b363beba335df4"] = { "Anche il mio talento ha un limite, e tu l'hai raggiunto. Congratulazioni, {name}. La tua prossima tappa dovrebbe essere l'⟦Camp Mojache=Accampamento Mojache⟧, a Feralas. Lì vive la tauren Hahrana Ironhide, famosa per la sua abilità.", "." },
  ["20b911201703cd07"] = { "Oh sì, la muta: non perderla. Alcuni della mia stirpe nelle ⟦Burning Steppes=Steppe Ardenti⟧ saprebbero forgiare oggetti che solo la muta dello Stormo dei Draghi Neri può rinforzare.", "." },
  ["20bd221469986c91"] = { "Intorno a Dolanaar troverai numerosi istruttori con secoli di esperienza da trasmetterti. Da chi vuoi che ti indirizzi?", "." },
  ["20c05d40cab75dec"] = { "Eh? Non ho tempo per chiacchierare, mio padre vuole che finisca quest'ordine per lui.", "." },
  ["20c297a40a7c6b48"] = { "⟦Ashenvale=Valtetra⟧ è una foresta rigogliosa, traboccante di vita. È un piacere percorrerne i sentieri segreti in cerca di erbe, ma bisogna stare attenti. La foresta non è priva di pericoli.", "." },
  ["20c921c1a9d76ce3"] = { "Il villaggio di Astranaar, a ⟦Ashenvale=Valtetra⟧, è l'attuale dimora dell'anziana Riversong.", "." },
  ["20d3ee13a15a1d34"] = { "Tutti coloro che tradiscono Ragnaros devono morire!", "." },
  ["20da1a4db2e67956"] = { "Mi divertirò, {class}.", "." },
  ["20e64c17d95154c1"] = { "Svegliati!", "." },
  ["20e8e52b08baca70"] = { "Ecco fatto, {name}. La tossina è pronta.", "." },
  ["20eb67bf45e4bd67"] = { "Temo che avrai bisogno di più addestramento prima che io possa condividere con te le mie conoscenze.", "." },
  ["20fbbdd8d018a08a"] = { "Ehi, Pratt, puoi insegnarmi di nuovo a fare delle ⟦Wild Leather Leggings=Gambiere di Cuoio Selvatico⟧?", "." },
